{
  "name": "Trabajo Cerca",
  "short_name": "Trabajo Cerca",
  "id": "./",
  "start_url": "./",
  "scope": "./",
  "display": "standalone",
  "display_override": [
    "standalone"
  ],
  "orientation": "any",
  "background_color": "#f8faf5",
  "theme_color": "#06231c",
  "description": "Oportunidades laborales, personas y servicios locales en Malleco y Biobío norte.",
  "categories": [
    "business",
    "productivity"
  ],
  "prefer_related_applications": false,
  "share_target": {
    "action": "./share-target",
    "method": "POST",
    "enctype": "multipart/form-data",
    "params": {
      "title": "share_title",
      "text": "share_text",
      "url": "share_url",
      "files": [
        {
          "name": "share_image",
          "accept": [
            "image/*"
          ]
        }
      ]
    }
  },
  "icons": [
    {
      "src": "./icon-192.png?v=crisp-20261120",
      "sizes": "192x192",
      "type": "image/png",
      "purpose": "any"
    },
    {
      "src": "./icon-512.png?v=crisp-20261120",
      "sizes": "512x512",
      "type": "image/png",
      "purpose": "any"
    },
    {
      "src": "./icon-maskable-512.png?v=crisp-20261120",
      "sizes": "512x512",
      "type": "image/png",
      "purpose": "maskable"
    }
  ]
}

const CACHE='trabajo-cerca-shell-icons-20261120-v2';
const SHARE_CACHE='trabajo-cerca-share-v1';
const CORE=['./','./manifest.webmanifest','./brand/trabajo-cerca-oficial.svg','./brand/trabajo-cerca-simbolo.svg','./icon-192.png','./icon-512.png','./icon-maskable-512.png'];
self.addEventListener('install',event=>{event.waitUntil((async()=>{
 const cache=await caches.open(CACHE);await cache.addAll(CORE);
 try{const html=await (await fetch('./',{cache:'reload'})).text();
 const assets=[...html.matchAll(/(?:src|href)=["']([^"']+\.(?:js|css)(?:\?[^"']*)?)["']/g)].map(m=>new URL(m[1],self.registration.scope)).filter(u=>u.origin===self.location.origin&&/\/assets\//.test(u.pathname)).slice(0,30);
 await Promise.all(assets.map(async u=>{try{await cache.add(u.toString());}catch{}}));}catch{}
 await self.skipWaiting();})());});
self.addEventListener('activate',event=>{
  event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE&&key!==SHARE_CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()));
});
self.addEventListener('fetch',event=>{
  const request=event.request;
  const url=new URL(request.url);
  if(url.origin!==self.location.origin) return;
  if(request.method==='POST'&&url.pathname.endsWith('/share-target')){
    event.respondWith((async()=>{
      const form=await request.formData();
      const title=String(form.get('share_title')||'');
      const text=String(form.get('share_text')||'');
      const sharedUrl=String(form.get('share_url')||'');
      const file=form.get('share_image');
      const params=new URLSearchParams({share_target:'1'});
      if(title) params.set('share_title',title);
      if(text) params.set('share_text',text);
      if(sharedUrl) params.set('share_url',sharedUrl);
      if(file&&typeof file.arrayBuffer==='function'&&file.size>0){
        const mime=String(file.type||'').toLowerCase();
        if(!['image/jpeg','image/png','image/webp'].includes(mime)||file.size>3*1024*1024)
          return new Response('Imagen incompatible o mayor de 3 MB.',{status:413});
        const cache=await caches.open(SHARE_CACHE);
        const sharedRequest=new Request(new URL('./__shared_job_image__',self.registration.scope));
        await cache.put(sharedRequest,new Response(file,{headers:{
          'Content-Type':mime,'X-TC-Shared-At':String(Date.now()),
          'Cache-Control':'private, no-store'
        }}));
        params.set('share_image','1');
      }
      return Response.redirect(new URL('./?'+params.toString(),self.registration.scope).toString(),303);
    })());
    return;
  }
  if(request.method!=='GET') return;
  if(url.pathname.startsWith('/api/')){event.respondWith(fetch(request));return;}
  // Reuse immutable hashed app code without a network request every visit.
  if(/\/assets\/[^/]+\.(?:js|css)$/.test(url.pathname)){
    event.respondWith((async()=>{
      const cache=await caches.open(CACHE),stored=await cache.match(request);
      if(stored)return stored;
      const r=await fetch(request);if(r.ok)event.waitUntil(cache.put(request,r.clone()));return r;
    })());return;
  }
  // SVG campaign artwork: render immediately from cache, refresh unobtrusively.
  if(/\/house-creatives\/[^/]+\.svg$/.test(url.pathname)){
    event.respondWith((async()=>{
      const cache=await caches.open(CACHE),stored=await cache.match(request);
      if(stored){
        event.waitUntil(fetch(request).then(r=>r.ok?cache.put(request,r):undefined).catch(()=>undefined));
        return stored;
      }
      const r=await fetch(request);if(r.ok)event.waitUntil(cache.put(request,r.clone()));return r;
    })());return;
  }
  if(url.pathname.endsWith('/__shared_job_image__')){
    event.respondWith((async()=>{
      const cache=await caches.open(SHARE_CACHE);
      const response=await cache.match(request);
      if(!response) return new Response('',{status:404});
      const savedAt=Number(response.headers.get('X-TC-Shared-At')||0);
      event.waitUntil(cache.delete(request));
      if(!Number.isFinite(savedAt)||savedAt<=0||Date.now()-savedAt>5*60*1000)
        return new Response('La imagen compartida caducó.',{status:410});
      return response;
    })());
    return;
  }
  const privateQuery=['security-proof','radar-proof','radar-local-proof','radar-public-proof','radar-receiver-proof','admin-proof'];
  if(privateQuery.some(key=>url.searchParams.has(key))||url.pathname.includes('__appdeploy')){event.respondWith(fetch(request));return;}
  if(request.mode==='navigate'){
    event.respondWith(fetch(request).then(response=>{
      if(response.ok&&url.pathname===new URL(self.registration.scope).pathname&&/text\/html/i.test(response.headers.get('content-type')||'')&&!/private|no-store/i.test(response.headers.get('cache-control')||'')){const copy=response.clone();void caches.open(CACHE).then(cache=>cache.put('./',copy));}
      return response;
    }).catch(async()=>await caches.match('./')||new Response('Sin conexión. Abre Trabajo Cerca cuando recuperes internet.',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}})));
    return;
  }
  event.respondWith(fetch(request).then(response=>{
    if(response.ok&&!/private|no-store/i.test(response.headers.get('cache-control')||'')){
      const copy=response.clone();
      void caches.open(CACHE).then(cache=>cache.put(request,copy));
    }
    return response;
  }).catch(()=>caches.match(request)));
});

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { Resvg } from '@resvg/resvg-js';

// Generate native Android/Chrome icons from exactly the same SVG displayed
// in the splash screen and the web header. No separately-maintained old icon.
const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const artwork = readFileSync(resolve(root,'public/brand/trabajo-cerca-oficial.svg'),'utf8');
if (!artwork.includes('Trabajo Cerca') || !artwork.includes('viewBox="0 0 1024 1024"')) {
  throw new Error('No se encontró el logo oficial SVG esperado.');
}
const jobs = [
  ['icon-192.png', 192, artwork],
  ['icon-512.png', 512, artwork],
  // Safe zone for Android maskable icons, with a solid light background.
  ['icon-maskable-512.png', 512, artwork.replace('viewBox="0 0 1024 1024"',
    'viewBox="-195 -195 1414 1414"')]
];
for (const [filename, size, source] of jobs) {
  const png = new Resvg(source, {
    fitTo: { mode:'width', value:size },
    font: {loadSystemFonts:true},
    background: '#ffffff'
  }).render().asPng();
  if (png.byteLength < 4000 || !Buffer.from(png).subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]))) {
    throw new Error('Falló la producción del icono '+filename);
  }
  const file = resolve(root,'public',filename);
  writeFileSync(file,png);
  console.log('PWA_ICON_READY',filename, size, png.length);
}

export type AdMedia={storagePath?:string;approved?:boolean;reviewedAt?:string;imageUrl?:string};
export const validCreativePath=(path:unknown):path is string=>typeof path==='string'&&/^house-creatives\/[a-f0-9]{64}\.(png|jpg|webp)$/.test(path);
export function safeAdImage(url:unknown):string|undefined {
 if(typeof url!=='string')return;
 if(/^\/resources\/house-(professionals|advertisers|employers|explore|inclusion|local-business)-photo-v2-(640|1200)\.webp$/.test(url))return url;
 const pinnedPhotoOrigin = 'https://raw.githubusercontent.com/mrvvergara-afk/Trabajo-Cerca-/c445112b9cdb78adfce9d8065e32411c4f412c4b/integrations/appdeploy/house-ads/public/resources/';
 if (url.startsWith(pinnedPhotoOrigin) && /^house-(professionals|advertisers|employers|explore|inclusion|local-business)-photo-v2-(640|1200)\.webp$/.test(url.slice(pinnedPhotoOrigin.length))) return url;
 if(/^\/house-creatives\/[a-z-]+\.svg$/.test(url))return url;
 try{const u=new URL(url);if(u.protocol!=='https:'||u.username||u.password)return;
 if(u.hostname.endsWith('.amazonaws.com')||u.hostname.endsWith('.appdeploy.ai'))return u.href;}catch{/* Untrusted arbitrary external URL is not an approved creative. */}
}

import type { CommercialAd, Slot } from './house-ads';
export const COMMERCIAL_PLACES = ['Angol','Collipulli','Ercilla','Renaico','Mininco','Los Sauces','Purén','Traiguén','Lumaco','Nacimiento','Negrete','Mulchén','Victoria'];
export type CommercialConfig = {
  revision:string; launchAt:string|null; founderClosesAt:string|null; founderWindowDays:number;
  founderSlots:number; founderDays:number; foundersUsed:number; standardDays:number;
  enabled:boolean; standardEnabled:boolean; message:string; conditions:string;
  plans:{id:string;priceCLP:number;days:number;approved:false;vat:'pending'|'included'|'excluded'}[];
};
export const COMMERCIAL_DEFAULTS:CommercialConfig = {
  revision:'commercial-defaults-v1',launchAt:null,founderClosesAt:null,founderWindowDays:30,
  founderSlots:20,founderDays:30,foundersUsed:0,standardDays:14,enabled:true,standardEnabled:true,
  message:'Conoce nuestra promoción gratuita de lanzamiento.',
  conditions:'Una promoción por negocio elegible, sujeta a revisión. Sin cobros ni renovación automática.',
  plans:[['emprendedor',2990],['local',5990],['destacado',9990],['empresa',19990]].map(([id,price])=>({id:String(id),priceCLP:Number(price),days:30,approved:false,vat:'pending'})),
};
export function promotionOffer(c:CommercialConfig,now=Date.now()) {
  const remaining=Math.max(0,c.founderSlots-c.foundersUsed);
  if(!c.enabled)return {kind:'paused',days:0,remaining,message:'La promoción está pausada.',conditions:c.conditions};
  if(!c.launchAt||now<Date.parse(c.launchAt))return {kind:'not_launched',days:0,remaining,message:'La fecha de lanzamiento aún no está habilitada. Puedes registrar tu interés.',conditions:c.conditions};
  const end=c.founderClosesAt?Date.parse(c.founderClosesAt):Date.parse(c.launchAt)+c.founderWindowDays*86400000;
  if(now<end&&remaining>0)return {kind:'founder',days:c.founderDays,remaining,message:c.message,conditions:c.conditions};
  if(c.standardEnabled)return {kind:'standard',days:c.standardDays,remaining:0,message:c.message,conditions:c.conditions};
  return {kind:'closed',days:0,remaining:0,message:'La promoción está cerrada. Puedes registrar tu interés.',conditions:c.conditions};
}
export function validateCommercialConfig(raw:unknown,current:CommercialConfig):CommercialConfig {
  const x=raw as CommercialConfig;
  if(!x||typeof x!=='object')throw Error('Configuración inválida.');
  for(const k of ['founderSlots','founderDays','standardDays','founderWindowDays'] as const)
    if(!Number.isInteger(x[k])||x[k]<1||x[k]>(k==='founderSlots'?10000:365))throw Error('Cupos o duración inválidos.');
  if(x.founderSlots<current.foundersUsed)throw Error('No se pueden quitar cupos ya otorgados.');
  for(const k of ['launchAt','founderClosesAt'] as const)if(x[k]!==null&&(typeof x[k]!=='string'||!Number.isFinite(Date.parse(x[k]))))throw Error('Fecha inválida.');
  if(x.founderClosesAt&&(!x.launchAt||Date.parse(x.founderClosesAt)<=Date.parse(x.launchAt)))throw Error('Cierre anterior al lanzamiento.');
  if(current.foundersUsed&&x.launchAt!==current.launchAt)throw Error('No se puede reiniciar un lanzamiento con beneficios otorgados.');
  if(typeof x.enabled!=='boolean'||typeof x.standardEnabled!=='boolean'||typeof x.message!=='string'||!x.message.trim()||x.message.length>300||typeof x.conditions!=='string'||!x.conditions.trim()||x.conditions.length>1000)throw Error('Mensajes o estado inválidos.');
  if(!Array.isArray(x.plans)||x.plans.length>12||new Set(x.plans.map(p=>p.id)).size!==x.plans.length)throw Error('Planes inválidos.');
  const plans=x.plans.map(p=>{if(!/^[a-z0-9-]{1,40}$/.test(p.id)||!Number.isSafeInteger(p.priceCLP)||p.priceCLP<0||p.priceCLP>10000000||!Number.isInteger(p.days)||p.days<1||p.days>365||!['pending','included','excluded'].includes(p.vat))throw Error('Tarifa o IVA inválido.');return {id:p.id,priceCLP:p.priceCLP,days:p.days,approved:false as const,vat:p.vat};});
  return {...current,launchAt:x.launchAt,founderClosesAt:x.founderClosesAt,founderSlots:x.founderSlots,founderDays:x.founderDays,standardDays:x.standardDays,founderWindowDays:x.founderWindowDays,enabled:x.enabled,standardEnabled:x.standardEnabled,message:x.message.trim(),conditions:x.conditions.trim(),plans};
}
export function commercialPlaceMatches(communes:string[]|undefined,place:string) {
  if (!communes?.length) return false;
  if (communes.includes('Todas')) return true;
  if (place === 'Todas') return false;
  return communes.includes(place) || (place === 'Collipulli' && communes.includes('Mininco')) || (place === 'Mininco' && communes.includes('Collipulli'));
}
export function businessIdentity(name:string) {
  return name.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es-CL').replace(/[^a-z0-9]/g,'');
}
export function selectCommercial(ads:CommercialAd[],place:string,turn:number,now=Date.now(),page='home') {
  const selected:CommercialAd[]=[];const used=new Set<string>();
  for(const slot of ['search','listing','featured','form'] as Slot[]) {
    const eligible=ads.filter(a=>a.status==='active'&&Date.parse(a.startAt)<=now&&now<Date.parse(a.endAt)&&commercialPlaceMatches(a.communes,place)&&(a.pages??['home']).includes(page)&&(a.placements??['search','listing']).includes(slot));
    const reserved=eligible.filter(a=>a.adType!=='COMMERCIAL_FREE').sort((a,b)=>(b.adType==='COMMERCIAL_PAID'?1:0)-(a.adType==='COMMERCIAL_PAID'?1:0)||(b.communes.includes(place)&&place!=='Todas'?1:0)-(a.communes.includes(place)&&place!=='Todas'?1:0)||b.priority-a.priority||a.id.localeCompare(b.id));
    let chosen=reserved[0];
    if(!chosen){
      const unused=eligible.filter(a=>!used.has(businessIdentity(a.businessName)));
      const pool=(unused.length?unused:eligible).sort((a,b)=>(b.communes.includes(place)&&place!=='Todas'?1:0)-(a.communes.includes(place)&&place!=='Todas'?1:0)||b.priority-a.priority||a.id.localeCompare(b.id));
      if(pool.length){const first=pool[0];const tier=pool.filter(a=>a.priority===first.priority&&a.communes.includes(place)===first.communes.includes(place));chosen=tier[((turn%tier.length)+tier.length)%tier.length];}
    }
    if(chosen){selected.push({...chosen,placements:[slot]});used.add(businessIdentity(chosen.businessName));}
  }
  // One record may reserve both placements. Preserve both rather than duplicate IDs.
  const byId=new Map<string,CommercialAd>();
  for(const ad of selected){const old=byId.get(ad.id);byId.set(ad.id,old?{...old,placements:[...old.placements!,...ad.placements!]}:ad);}
  return [...byId.values()];
}
